-- Phase 538 tests (UNION-10: 21 shared functions carry the merged text). TEST DATABASE ONLY (a local throwaway Postgres built from the owner paste chain, tests/sql/run_all_union.sh). Prints PASS / FAIL per check.
-- Test users and items are neutral test_* ids. Run on the final database (needs phase539 for the audit, so it checks the md5 itself).
\set ON_ERROR_STOP off
\set o '00000000-0000-0000-0000-00000000f538'
create schema if not exists t538;
create table if not exists t538.res (name text, ok boolean);
truncate t538.res;
create or replace function t538.chk(p_name text, p_ok boolean) returns void language plpgsql as $$
begin insert into t538.res values (p_name, coalesce(p_ok, false)); raise notice '% %', case when coalesce(p_ok, false) then 'PASS' else 'FAIL' end, p_name; end $$;
create or replace function t538.def(p_sig text) returns text language sql as $$ select pg_get_functiondef(p_sig::regprocedure) $$;
create or replace function t538.has(p_sig text, p_text text) returns boolean language sql as $$ select position(p_text in pg_get_functiondef(p_sig::regprocedure)) > 0 $$;

\echo == T1 every function of this file has the merged text (the md5 is recorded by phase539; this suite runs on the final database)
select t538.chk('T1a all 21 functions exist', (select count(*) = 21 from unnest(array['public.record_sale2(uuid,integer,jsonb,numeric,jsonb,text,text,text,text,boolean,timestamp with time zone,text,numeric)', 'public.rollout_mode(text,integer)', 'public.sales_channel_save(integer,text,text,text,text,integer,text,text,boolean)', 'public.save_purchase(uuid,uuid,uuid,integer,text,date,jsonb,numeric,text,text,text,uuid,text)', 'public.save_supplier(uuid,jsonb)', 'public.sheet_sync_all()', 'public.shelf_life_for(uuid,date)', 'public.stock_blind_active(text,integer)', 'public.stock_count_adjust(uuid,integer,numeric,text,text,uuid)', 'public.stock_opening(uuid,integer,numeric,numeric,text,text,uuid)', 'public.stock_post(uuid,integer,numeric,text,text,text,numeric,bigint,timestamp with time zone,text,bigint,text,uuid,uuid)', 'public.stock_receive_transfer(uuid,numeric,text,numeric,text)', 'public.supplier_pick()', 'public.supplier_refund(uuid,integer,numeric,text,text,text,text,text,uuid)', 'public.template_for(text,integer)', 'public.unit_factor(uuid,text,text)', 'public.urgent_alerts(timestamp with time zone)', 'public.void_supplier_payment(bigint,text)', 'public.void_supplier_refund(bigint,text)', 'public.wastage_decide(uuid,boolean,text)', 'public.year_close_list()']) f where to_regprocedure(f) is not null));
select t538.chk('T1b the audit says merged for all of them', (select count(*) = 0 from public._union_audit() a where a.fn = any (array['public.record_sale2(uuid,integer,jsonb,numeric,jsonb,text,text,text,text,boolean,timestamp with time zone,text,numeric)', 'public.rollout_mode(text,integer)', 'public.sales_channel_save(integer,text,text,text,text,integer,text,text,boolean)', 'public.save_purchase(uuid,uuid,uuid,integer,text,date,jsonb,numeric,text,text,text,uuid,text)', 'public.save_supplier(uuid,jsonb)', 'public.sheet_sync_all()', 'public.shelf_life_for(uuid,date)', 'public.stock_blind_active(text,integer)', 'public.stock_count_adjust(uuid,integer,numeric,text,text,uuid)', 'public.stock_opening(uuid,integer,numeric,numeric,text,text,uuid)', 'public.stock_post(uuid,integer,numeric,text,text,text,numeric,bigint,timestamp with time zone,text,bigint,text,uuid,uuid)', 'public.stock_receive_transfer(uuid,numeric,text,numeric,text)', 'public.supplier_pick()', 'public.supplier_refund(uuid,integer,numeric,text,text,text,text,text,uuid)', 'public.template_for(text,integer)', 'public.unit_factor(uuid,text,text)', 'public.urgent_alerts(timestamp with time zone)', 'public.void_supplier_payment(bigint,text)', 'public.void_supplier_refund(bigint,text)', 'public.wastage_decide(uuid,boolean,text)', 'public.year_close_list()']) and a.state <> 'merged') and (select count(*) from public._union_audit() a where a.fn = any (array['public.record_sale2(uuid,integer,jsonb,numeric,jsonb,text,text,text,text,boolean,timestamp with time zone,text,numeric)', 'public.rollout_mode(text,integer)', 'public.sales_channel_save(integer,text,text,text,text,integer,text,text,boolean)', 'public.save_purchase(uuid,uuid,uuid,integer,text,date,jsonb,numeric,text,text,text,uuid,text)', 'public.save_supplier(uuid,jsonb)', 'public.sheet_sync_all()', 'public.shelf_life_for(uuid,date)', 'public.stock_blind_active(text,integer)', 'public.stock_count_adjust(uuid,integer,numeric,text,text,uuid)', 'public.stock_opening(uuid,integer,numeric,numeric,text,text,uuid)', 'public.stock_post(uuid,integer,numeric,text,text,text,numeric,bigint,timestamp with time zone,text,bigint,text,uuid,uuid)', 'public.stock_receive_transfer(uuid,numeric,text,numeric,text)', 'public.supplier_pick()', 'public.supplier_refund(uuid,integer,numeric,text,text,text,text,text,uuid)', 'public.template_for(text,integer)', 'public.unit_factor(uuid,text,text)', 'public.urgent_alerts(timestamp with time zone)', 'public.void_supplier_payment(bigint,text)', 'public.void_supplier_refund(bigint,text)', 'public.wastage_decide(uuid,boolean,text)', 'public.year_close_list()'])) = (select count(*) from unnest(array['public.record_sale2(uuid,integer,jsonb,numeric,jsonb,text,text,text,text,boolean,timestamp with time zone,text,numeric)', 'public.rollout_mode(text,integer)', 'public.sales_channel_save(integer,text,text,text,text,integer,text,text,boolean)', 'public.save_purchase(uuid,uuid,uuid,integer,text,date,jsonb,numeric,text,text,text,uuid,text)', 'public.save_supplier(uuid,jsonb)', 'public.sheet_sync_all()', 'public.shelf_life_for(uuid,date)', 'public.stock_blind_active(text,integer)', 'public.stock_count_adjust(uuid,integer,numeric,text,text,uuid)', 'public.stock_opening(uuid,integer,numeric,numeric,text,text,uuid)', 'public.stock_post(uuid,integer,numeric,text,text,text,numeric,bigint,timestamp with time zone,text,bigint,text,uuid,uuid)', 'public.stock_receive_transfer(uuid,numeric,text,numeric,text)', 'public.supplier_pick()', 'public.supplier_refund(uuid,integer,numeric,text,text,text,text,text,uuid)', 'public.template_for(text,integer)', 'public.unit_factor(uuid,text,text)', 'public.urgent_alerts(timestamp with time zone)', 'public.void_supplier_payment(bigint,text)', 'public.void_supplier_refund(bigint,text)', 'public.wastage_decide(uuid,boolean,text)', 'public.year_close_list()']))); 
select md5(string_agg(md5(rtrim(pg_get_functiondef(to_regprocedure(f)), E'\n')), '' order by f)) as hb, (select count(*) from public._union_fn_backup) as nb from unnest(array['public.record_sale2(uuid,integer,jsonb,numeric,jsonb,text,text,text,text,boolean,timestamp with time zone,text,numeric)', 'public.rollout_mode(text,integer)', 'public.sales_channel_save(integer,text,text,text,text,integer,text,text,boolean)', 'public.save_purchase(uuid,uuid,uuid,integer,text,date,jsonb,numeric,text,text,text,uuid,text)', 'public.save_supplier(uuid,jsonb)', 'public.sheet_sync_all()', 'public.shelf_life_for(uuid,date)', 'public.stock_blind_active(text,integer)', 'public.stock_count_adjust(uuid,integer,numeric,text,text,uuid)', 'public.stock_opening(uuid,integer,numeric,numeric,text,text,uuid)', 'public.stock_post(uuid,integer,numeric,text,text,text,numeric,bigint,timestamp with time zone,text,bigint,text,uuid,uuid)', 'public.stock_receive_transfer(uuid,numeric,text,numeric,text)', 'public.supplier_pick()', 'public.supplier_refund(uuid,integer,numeric,text,text,text,text,text,uuid)', 'public.template_for(text,integer)', 'public.unit_factor(uuid,text,text)', 'public.urgent_alerts(timestamp with time zone)', 'public.void_supplier_payment(bigint,text)', 'public.void_supplier_refund(bigint,text)', 'public.wastage_decide(uuid,boolean,text)', 'public.year_close_list()']) f \gset
