select t538.chk('T2 a second paste changes nothing', (select md5(string_agg(md5(rtrim(pg_get_functiondef(to_regprocedure(f)), E'\n')), '' order by f)) from unnest(array['public.record_sale2(uuid,integer,jsonb,numeric,jsonb,text,text,text,text,boolean,timestamp with time zone,text,numeric)', 'public.rollout_mode(text,integer)', 'public.sales_channel_save(integer,text,text,text,text,integer,text,text,boolean)', 'public.save_purchase(uuid,uuid,uuid,integer,text,date,jsonb,numeric,text,text,text,uuid,text)', 'public.save_supplier(uuid,jsonb)', 'public.sheet_sync_all()', 'public.shelf_life_for(uuid,date)', 'public.stock_blind_active(text,integer)', 'public.stock_count_adjust(uuid,integer,numeric,text,text,uuid)', 'public.stock_opening(uuid,integer,numeric,numeric,text,text,uuid)', 'public.stock_post(uuid,integer,numeric,text,text,text,numeric,bigint,timestamp with time zone,text,bigint,text,uuid,uuid)', 'public.stock_receive_transfer(uuid,numeric,text,numeric,text)', 'public.supplier_pick()', 'public.supplier_refund(uuid,integer,numeric,text,text,text,text,text,uuid)', 'public.template_for(text,integer)', 'public.unit_factor(uuid,text,text)', 'public.urgent_alerts(timestamp with time zone)', 'public.void_supplier_payment(bigint,text)', 'public.void_supplier_refund(bigint,text)', 'public.wastage_decide(uuid,boolean,text)', 'public.year_close_list()']) f) = :'hb' and (select count(*) from public._union_fn_backup) = :nb);

\echo == RESULT
select 'phase538 tests: ' || count(*) filter (where ok) || ' PASS, ' || count(*) filter (where not ok) || ' FAIL' as result from t538.res;
select 'RESULT pass=' || count(*) filter (where ok) || ' fail=' || count(*) filter (where not ok) from t538.res;
select name from t538.res where not ok;
